function save(manual=false){if(DEV_MODE)return;if(!started||!world||recoveryError)return;try{const busy=!!dialog||!!cinema?.busy;const value=checkpointValue({current:busy?null:saveValue(),stable:stableCheckpoint,busy});if(!value){saveFeedback?.changed();if(manual)notice('Finish this first conversation to create a checkpoint.');return;}localStorage.setItem(STORE,JSON.stringify(value));const profileSaved=writeJourneyProfile(localStorage,value);saveFeedback?.saved({checkpointOnly:busy,profileSaved});if(!busy&&!battle)stableCheckpoint=value;if(manual)notice(busy?'Checkpoint saved before this interaction. Finish it to keep your choice.':profileSaved?'Saved on this device.':'Game saved; traveller slot unavailable. Export a backup from Pause.');}catch(error){saveFeedback?.failed();if(manual)notice('Saving is unavailable. Export a backup from Pause to keep this journey.');console.error(error);}}


