 embodiedFeedback?.unlock();
 const s=world.state,candidates=fieldInteractionTargets(world).map(row=>({...row,d:Math.hypot(s.x-row.approach.xy[0]-.5,s.y-row.approach.xy[1]-.5)})).filter(v=>v.d<2.05&&clearInteractionApproach(world.scene,[s.x,s.y],v.approach)).sort((a,b)=>a.d-b.d);
