 if(candidates[0]){const nearest=candidates[0];if(nearest.object.requiresChoice){const group=candidates.filter(v=>v.object.requiresChoice&&v.object.choiceGroup===nearest.object.choiceGroup);if(group.length>1)return embodiedFeedback.choose({object:nearest.object,actions:group.map(v=>({label:v.object.label,action:()=>engageFieldObject(v.object)}))});}return engageFieldObject(nearest.object);}
 const door=world.scene.doors.find(d=>Math.hypot(s.x-d.xy[0]-.5,s.y-d.xy[1]-.5)<1.4);if(door&&clearInteractionApproach(world.scene,[s.x,s.y],door))return world.portal(door);
