function command(kind,tech){
 const h=tech&&spellActorId!==null?battle?.heroes.find(h=>h.id===spellActorId&&h.hp>0):selectedActor();if(!h)return notice('Choose a living crew member.');
 const t=kind==='guard'?h:selectedTarget(tech);if(!t)return;combatOrders.manual();
 if(!combatOrders.request(battle,world,h,kind,t,tech))return;
 uiMode='';$('#spell-menu').hidden=true;spellChoices=[];combatOrders.step(battle,world,0);syncBattleLeader();hud(true);
}

function useItem(){combatOrders.cancel();spellChoices=[];if(!battle)return;livingUI.close();fieldUI.close();goalUI.close();const h=selectedActor();if(!h)return notice('Wait for a ready crew member.');spellActorId=h.id;uiMode='tech';menuIndex=0;const menu=$('#spell-menu');menu.replaceChildren();delete menu.dataset.picker;menu.dataset.command='item';menu.hidden=false;for(const item of ITEMS.filter(i=>world.state.items[i.id]>0)){const b=document.createElement('button');b.textContent=item.name+' × '+world.state.items[item.id]+' · '+item.description;b.prepend(supplyCanvas(item,44));b.onclick=()=>{const actor=battle?.ready.find(a=>a.id===spellActorId);if(!battle||!applySupply(battle,world.state.items,item.id,actor,selectedTarget()))return notice('No suitable target, or this crew member is not ready.');menu.hidden=true;uiMode='';notice(item.name+' used.');hud(true);};menu.append(b);}if(!menu.children.length){const p=document.createElement('p');p.textContent='Your supply bag is empty. Shops and hidden caches hold more.';menu.append(p);}const close=document.createElement('button');close.textContent='Cancel';close.onclick=()=>{menu.hidden=true;uiMode='';};menu.append(close);}
function supplyBag(){togglePause(true);$('#pause-title').textContent='Supply bag';$('#pause-body').hidden=true;$('#party-panel').hidden=false;$('#party-panel').replaceChildren();appendWayglassBag($('#party-panel'),world.state,{onOpen(){if(battle)return notice('Unfold the Wayglass outside battle.');togglePause(false);observatory.open();},onGrid:openSkillGrid});for(const item of ITEMS.filter(i=>world.state.items[i.id]>0)){const p=document.createElement('p');p.textContent=item.name+' × '+world.state.items[item.id]+' — '+item.description;p.prepend(supplyCanvas(item,44));$('#party-panel').append(p);}if(!$('#party-panel').children.length)$('#party-panel').textContent='Your bag is empty. Search hidden caches or visit the market.';const back=document.createElement('button');back.textContent='Back';back.onclick=()=>togglePause(true);$('#party-panel').append(back);queueMicrotask(()=>back.focus());}

const quickTechniques=document.createElement('div');quickTechniques.id='quick-techniques';quickTechniques.setAttribute('aria-label','Selected crew moves');$('#commands .command-grid').before(quickTechniques);
for(const [id,kind]of [['attack','attack'],['mako','mako'],['personal','personal'],['guard','guard'],['item','item'],['retreat','retreat']])$('#cmd-'+id).prepend(commandIcon(kind,{size:22}));
let quickSignature='',quickMoves=[];
function refreshQuickTechniques(){
 if(!battle){quickTechniques.hidden=true;quickSignature='';quickMoves=[];return;}
 const h=selectedActor()||battle.heroes.find(h=>h.id===actorId)||battle.heroes[0];if(!h)return;
 quickTechniques.hidden=false;
 const recipes=h.loadout.map(slot=>compileLoadoutTechnique(slot,h,world.state));
 const signature=JSON.stringify([h.id,recipes]);
 if(signature!==quickSignature){quickSignature=signature;quickMoves=[];quickTechniques.replaceChildren();for(const tech of recipes.slice(0,4)){
  const b=document.createElement('button'),copy=document.createElement('span'),name=document.createElement('strong'),cost=document.createElement('small');b.type='button';b.className='quick-technique';b.append(techniqueIcon(tech,{size:38}),copy);name.textContent=tech.name;copy.append(name,cost);b.onclick=()=>{actorId=h.id;spellActorId=h.id;command('tech',tech);};quickTechniques.append(b);quickMoves.push({b,cost,tech,heroId:h.id});
 }}
 for(const row of quickMoves){const hero=battle.heroes.find(h=>h.id===row.heroId),q=techniquePreview(battle,hero,row.tech,{allowCharging:true});row.b.disabled=!q.enabled;row.cost.textContent=q.mp+' MP'+(q.hp?' + '+q.hp+' HP':'');row.b.title=q.reason||q.effectText;row.b.setAttribute('aria-label',row.tech.name+' · '+row.cost.textContent+' · '+(q.reason||q.effectText));row.b.classList.toggle('overdraw',q.enabled&&q.hp>0);}
}

function chooseBattleActor(id){if(!battle)return;combatOrders.cancel();const menu=$('#spell-menu'),kind=!menu.hidden&&!menu.dataset.picker?menu.dataset.command:null;actorId=id;if(kind){spellActorId=null;spellChoices=[];menu.hidden=true;uiMode='';if(kind==='item')useItem();else if(kind==='mako'||kind==='personal')showSpells(kind==='personal');}hud(true);}
function pickerControls(){return [...$('#spell-menu').querySelectorAll('button,select,summary')].filter(b=>!b.disabled&&b.getClientRects().length);}
function refreshTechniquePicker(){if(!battle||$('#spell-menu').hidden||$('#spell-menu').dataset.picker)return;for(const row of spellChoices){const h=battle.heroes.find(a=>a.id===row.heroId),quote=techniquePreview(battle,h,row.tech,{allowCharging:true});row.button.disabled=!quote.enabled;row.cost.textContent=quote.costText;row.detail.textContent=(quote.reason||quote.effectText)+(row.tech.signatureName?' · '+row.tech.signatureName:'');row.button.classList.toggle('overdraw',quote.enabled&&quote.hp>0);row.button.title=(quote.reason||quote.effectText)+(row.tech.signatureDetail?' · '+row.tech.signatureDetail:'');}}
function showSpells(personal=false){combatOrders.cancel();const h=selectedActor();if(!h)return notice('Wait for a ready crew member.');if(personal&&!h.learned||!personal&&!h.loadout.length)return notice('This crew member has not learned a technique yet.');livingUI.close();fieldUI.close();goalUI.close();spellActorId=h.id;uiMode='tech';menuIndex=0;const recipes=personal?data.skills.characters[h.id].skills.filter((v,i)=>h.learned&(1<<(7-i))).map(v=>personalTechnique(h,v.rank,v.name)):h.loadout.map(slot=>compileLoadoutTechnique(slot,h,world.state));const menu=$('#spell-menu');menu.replaceChildren();delete menu.dataset.picker;menu.dataset.command=personal?'personal':'mako';menu.hidden=false;spellChoices=[];if(personal){const signature=signatureMetadata(h.id),context=document.createElement('details'),summary=document.createElement('summary'),detail=document.createElement('p');context.className='battle-picker-context';summary.textContent=h.name+' · '+signature.signatureName;detail.textContent=signature.signatureDetail;context.append(summary,detail);menu.append(context);}for(const t of recipes){const b=document.createElement('button'),name=document.createElement('strong'),cost=document.createElement('span'),detail=document.createElement('small');b.className='technique-option';name.textContent=t.name+(t.rank>1?' · Rank '+t.rank:'');cost.className='technique-cost';const copy=document.createElement('span');copy.className='technique-copy';copy.append(name,cost,detail);b.append(techniqueIcon(t,{size:44}),copy);b.onclick=()=>command('tech',t);spellChoices.push({button:b,cost,detail,tech:t,heroId:h.id});menu.append(b);}const close=document.createElement('button');close.textContent='Cancel';close.onclick=()=>{menu.hidden=true;uiMode='';spellChoices=[];};menu.append(close);refreshTechniquePicker();queueMicrotask(()=>pickerControls()[0]?.focus({preventScroll:true}));}

const input={buttonDown(button,source='external'){if(document.querySelector('.traveller-veil')){document.dispatchEvent(new CustomEvent('traveller-input',{detail:button}));return;}if(observatory?.active)return;if(journey.active)return;if(cinema?.busy){if(['a','b','start'].includes(button))cinema.finish();return;}if(document.querySelector('#film-room')?.open)return;let set=held.get(source);if(!set){set=new Set();held.set(source,set);}if(set.has(button))return;set.add(button);buttons.add(button);edge(button);},buttonUp(button,source='external'){const set=held.get(source);set?.delete(button);if(set&&!set.size)held.delete(source);if(![...held.values()].some(s=>s.has(button)))buttons.delete(button);}};
function releaseMovement(){held.clear();buttons.clear();if(renderer)renderer.locomotion=null;stick?.releaseAll();face?.releaseAll();}
function release(){releaseMovement();worldGestures?.cancel();world?.worldControls?.cancelAction('Input released.');}
function edge(button){if(!started){if(button==='a'||button==='start'){const next=$('#continue:not([hidden])')||$('#play');next.click();}return;}if(button==='start'){togglePause();return;}if(paused){const list=[...$('#pause').querySelectorAll('button,select,input,summary,a[href]')].filter(e=>e.getClientRects().length&&!e.disabled),i=list.indexOf(document.activeElement);if(button==='a')document.activeElement?.click();if(['left','right'].includes(button)&&document.activeElement?.tagName==='SELECT'){const e=document.activeElement;e.selectedIndex=(e.selectedIndex+(button==='right'?1:e.options.length-1))%e.options.length;e.onchange?.();}if(button==='b')togglePause(false);if(['up','down'].includes(button))list[(i+(button==='down'?1:list.length-1))%list.length]?.focus();return;}if(dialog){if(button==='b'&&dialog.choices){const leave=dialog.choices.find(c=>/^(leave|stay|decide later)/i.test(c.label));if(leave){clearDialog();leave.action();save();return;}}if(dialog.choices&&['up','down','left','right'].includes(button)&&(['up','down'].includes(button)||!buttons.has('up')&&!buttons.has('down'))){dialog.choiceIndex=(dialog.choiceIndex+(['down','right'].includes(button)?1:dialog.choices.length-1))%dialog.choices.length;paintDialog();}if(button==='a')advanceDialog();return;}
 if(button==='x'){battle?showSpells():openMako();return;}if(button==='y'&&!battle){partyMenu();return;}if(button==='y'&&battle){const ready=battle.heroes.filter(h=>h.hp>0);if(ready.length)chooseBattleActor(ready[(ready.findIndex(h=>h.id===actorId)+1)%ready.length].id);return;}
 if(button==='l'||button==='r'){if(battle){combatOrders.cancel();const list=battle.livingEnemies,i=list.findIndex(e=>e.id===target);target=list[(i+(button==='r'?1:list.length-1))%list.length]?.id;hud(true);}return;}
 if(button==='b'){if(battle){combatOrders.cancel();flow.setAuto(false);}if(uiMode==='tech'){$('#spell-menu').hidden=true;uiMode='';}return;}
 if(button==='a'){if(uiMode==='tech'){const list=pickerControls();if(list.length)(list.includes(document.activeElement)?document.activeElement:list[menuIndex%list.length])?.click();}else battle?command('attack'):doInteract();}
 if(uiMode==='tech'&&['left','right'].includes(button)&&document.activeElement?.tagName==='SELECT'){const select=document.activeElement;select.selectedIndex=(select.selectedIndex+(button==='right'?1:select.options.length-1))%select.options.length;select.onchange?.();return;}if(uiMode==='tech'&&['left','right'].includes(button)&&document.activeElement?.tagName!=='SELECT'&&battleLayout.turnPage(button==='right'?1:-1)){return;}if(uiMode==='tech'&&(button==='up'||button==='down')){const list=pickerControls();if(!list.length)return;const focused=list.indexOf(document.activeElement);menuIndex=((focused>=0?focused:menuIndex)+(button==='down'?1:list.length-1))%list.length;list.forEach((b,i)=>b.classList.toggle('selected',i===menuIndex));list[menuIndex]?.focus({preventScroll:true});if(!battleLayout.reveal(list[menuIndex]))list[menuIndex]?.scrollIntoView({block:'nearest',inline:'nearest'});}
}
let stick,face;stick=bindDigitalJoystick($('#joystick'),{player:()=>input,active:()=>started&&!paused&&(!dialog||!!dialog.choices)});face=bindTouchControls(document.querySelectorAll('[data-button]'),{player:()=>input,active:()=>started&&!paused});const touchLayout=mountTouchLayout($('#touch'),{settings:$('#pause-body'),onRecover:()=>{release();setWorldZoom(null);},onChange:()=>{release();renderer?.resize();}});
const keymap={ArrowUp:'up',ArrowDown:'down',ArrowLeft:'left',ArrowRight:'right',KeyX:'a',KeyZ:'b',KeyS:'x',KeyA:'y',KeyQ:'l',KeyW:'r',Enter:'start',ShiftLeft:'select'};
window.addEventListener('keydown',e=>{if(e.target.closest?.('.constellation-atlas,.recipe-loom'))return;if(cisternJourney?.active||!started||observatory?.active||['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if(e.code==='Escape'){e.preventDefault();togglePause();return;}const b=keymap[e.code];if(b){e.preventDefault();if(!e.repeat)input.buttonDown(b,'keyboard');}});window.addEventListener('keyup',e=>{const b=keymap[e.code];if(b)input.buttonUp(b,'keyboard');});window.addEventListener('blur',()=>{release();if(cinema?.busy)cinema.finish();if(journey.active)journey.close(true);if(started&&!paused)togglePause(true);});
let oldPad=0,previousPadDirections=[];
function pollPad(){const pad=Array.from(navigator.getGamepads?.()||[]).find(p=>p?.connected);if(!pad){previousPadDirections=[];if(oldPad){for(const b of Object.keys(keymap).map(k=>keymap[k]))input.buttonUp(b,'gamepad');oldPad=0;}return;}const mapping=['a','b','x','y','l','r',null,null,'select','start',null,null,'up','down','left','right'];let mask=0;mapping.forEach((b,i)=>{if(b&&pad.buttons[i]?.pressed)mask|=1<<i;});previousPadDirections=axisDirections(pad.axes?.[0]||0,pad.axes?.[1]||0,previousPadDirections);for(const direction of previousPadDirections){const bit={up:12,down:13,left:14,right:15}[direction];mask|=1<<bit;}mapping.forEach((b,i)=>{if(!b)return;if((mask&1<<i)&&!(oldPad&1<<i))input.buttonDown(b,'gamepad');if(!(mask&1<<i)&&(oldPad&1<<i))input.buttonUp(b,'gamepad');});oldPad=mask;}
function togglePause(value=!paused){if(cisternJourney?.active)return;if(recoveryError){if(value===false)notice('Load your last save or choose a preserved traveller to continue.');return;}if(!started||observatory?.active||cinema?.busy||journey.active)return;paused=value;playtest?.record('pause',{paused});if(paused){combatOrders.cancel();questGuide?.interrupt('menu');path=[];arrivalAction=null;}release();$('#pause').hidden=!paused;syncSoundscape();cameraZoomControls?.update();if(paused){voices.stop();syncSoundscape();$('#pause-title').textContent='The journey';$('#pause-overview')?.remove();const overview=pauseOverview(world);overview.id='pause-overview';$('#pause-body').prepend(overview);queueMicrotask(()=>$('#resume').focus());$('#pause-body').hidden=false;const purpose=journeyPurpose(world.state);$('#journal-goal').textContent=purpose.aim+' '+purpose.why+' Next: '+world.objectiveText();$('#journal-discoveries').textContent=(world.state.discoveryLog||[]).slice(-3).map(x=>x.text).join(' ')+(world.state.exploration?' Hidden caches: '+world.state.exploration.found.length+'/72 · Keepsakes: '+world.state.exploration.relics.length+'/24':'');$('#mako-panel').hidden=true;$('#party-panel').hidden=true;}else {syncSoundscape();if(dialog)paintDialog();}}
function openLegacyMako(makoId=null,heroId=null){makoId=typeof makoId==='string'?makoId:null;if(!started)return;if(!world.state.cores.length)return notice('Recover a core pattern from Rook’s clay reader first.');if(battle)return showSpells();togglePause(true);$('#pause-title').textContent='Mako • linked crystal craft';$('#pause-body').hidden=true;$('#mako-panel').hidden=false;paintMako(world.state.recruited.includes(heroId)?heroId:world.state.party[0]);if(makoId)queueMicrotask(()=>{const select=$('#mako-panel .rare-mako-slot select');select?.focus();select?.closest('label').classList.add('wayglass-equipment-cue');});}
function paintMako(id){const focusLabel=document.activeElement?.getAttribute('aria-label');const h=world.state.heroes[id],panel=$('#mako-panel');panel.replaceChildren();const tabs=document.createElement('div');tabs.className='tabs';for(const c of world.state.recruited){const b=document.createElement('button');b.textContent=CREW[c].name;b.classList.toggle('selected',c===id);b.onclick=()=>paintMako(c);tabs.append(b);}panel.append(tabs);const loom=document.createElement('button');loom.textContent='Open the Mako recipe loom';loom.onclick=()=>panel.replaceChildren(recipeLoom({world,onSave:()=>save(),onBack:()=>paintMako(id)}));panel.append(loom);const builds=document.createElement('button');builds.textContent='Shape build constellations';builds.onclick=openSkillGrid;panel.append(builds);
 const p=document.createElement('p');p.className='hint';p.textContent=`${h.name}: ${CREW[id].affinity} affinity. Core AP unlocks ranks at 35 and 120. Link consumes a charged partner's MP and gauge; Rank 2 permits a trio. Overdraw costs HP and strain. Guard recovers MP and strain.`;panel.append(p);
 h.loadout.forEach((slot,i)=>{const row=document.createElement('div');row.className='socket-row';const label=document.createElement('strong');label.textContent='LINK '+(i+1);const c=document.createElement('select'),s=document.createElement('select');c.setAttribute('aria-label',h.name+' core '+(i+1));s.setAttribute('aria-label',h.name+' support '+(i+1));for(const core of CORES.filter(v=>world.state.cores.includes(v.id))){const o=new Option(core.name+' · AP '+(h.ap[core.id]||0),core.id);c.add(o);}for(const support of SUPPORTS.filter(v=>world.state.supports.includes(v.id)))s.add(new Option(support.name,support.id));c.value=slot.core;s.value=slot.support;c.onchange=()=>{slot.core=c.value;delete slot.makoId;paintMako(id);save();};s.onchange=()=>{slot.support=s.value;paintMako(id);save();};row.append(label,c,s);panel.append(row);const tech=compileLoadoutTechnique(slot,h,world.state),desc=document.createElement('p');desc.className='recipe';desc.style.color=tech.color;desc.textContent=`${tech.name} · ${tech.cost} MP · Rank ${tech.rank} · ${tech.shape}${tech.interrupt?' · interrupts charged attacks':''}${tech.echo?' · repeats after a delay':''}${tech.counter?' · responds when struck':''}${tech.field?' · leaves a persistent field':''}`;panel.append(desc);appendRareMakoSlot(panel,world.state,id,i,{onChange(){paintMako(id);save();}});});
 const close=document.createElement('button');close.textContent='Return to game';close.className='primary';close.onclick=()=>togglePause(false);panel.append(close);queueMicrotask(()=>{const focus=focusLabel?[...panel.querySelectorAll('[aria-label]')].find(e=>e.getAttribute('aria-label')===focusLabel):null;(focus||panel.querySelector('button,select'))?.focus();});
}
function storyMenu(){togglePause(true);$('#pause-title').textContent='The story so far';$('#pause-body').hidden=true;const panel=$('#party-panel');panel.hidden=false;panel.replaceChildren();for(const entry of [...(world.state.story?.journal||[]),...(world.state.fieldNotes||[]).map(n=>({title:n.label,text:n.pages.join('\n')+(n.effects.length?'\n'+n.effects.join(' · '):'')})),...(world.state.exploration?.relics||[]).map(r=>({title:'Keepsake · '+r.name,text:r.text}))]){const article=document.createElement('article'),h=document.createElement('h3'),p=document.createElement('p');h.textContent=entry.title;p.textContent=entry.text;article.append(h,p);panel.append(article);}if(!panel.children.length){const p=document.createElement('p');p.textContent='Your current journey is preserved. New beginnings record their discoveries here.';panel.append(p);}const b=document.createElement('button');b.textContent='Return to game';b.onclick=()=>togglePause(false);panel.append(b);}
$('#story-button').onclick=storyMenu;
function openAdvancedSkillGrid(makoId=null,schoolId=null,heroId=null,nodeId=null,schoolNodeId=null){makoId=typeof makoId==='string'?makoId:null;togglePause(true);$('#pause-title').textContent='The Resonance Paths';$('#pause-body').hidden=true;const panel=$('#party-panel');panel.hidden=false;panel.replaceChildren(skillGrid({world,data,initialMakoId:makoId,initialSchoolId:schoolId,initialSchoolNodeId:schoolNodeId,initialHero:heroId,initialNodeId:nodeId,onCraft:openMako,onSave:()=>save(),onBack:()=>openCrewSetup(heroId),inBattle:!!battle}));}
