function formationMenu(){togglePause(true);$('#pause-title').textContent='Travelling crew';$('#pause-body').hidden=true;const panel=$('#party-panel');panel.hidden=false;panel.replaceChildren();world.state.party.forEach((id,i)=>{const row=document.createElement('label');row.textContent='Position '+(i+1)+' ';const select=document.createElement('select');select.setAttribute('aria-label','Crew position '+(i+1));for(const c of world.state.recruited)select.add(new Option(CREW[c].name,c));select.value=id;select.onchange=()=>{const next=Number(select.value),other=world.state.party.indexOf(next);if(other>=0)world.state.party[other]=id;world.state.party[i]=next;renderer.scene(world);formationMenu();save();};row.append(select);panel.append(row);});const close=document.createElement('button');close.textContent='Return to game';close.onclick=()=>togglePause(false);panel.append(close);queueMicrotask(()=>panel.querySelector('select,button')?.focus());}
function openCrewSetup(heroId=null,makoId=null,schoolId=null){if(battle)return notice('Use Mako or Personal during the encounter. Crew setup opens between battles.');if(!started||dialog||cinema?.busy||observatory?.active)return;togglePause(true);$('#pause-title').textContent='Crew setup';$('#pause-body').hidden=true;$('#mako-panel').hidden=true;$('#party-panel').hidden=false;$('#party-panel').replaceChildren(crewSetup({world,data,initialHero:heroId,initialMakoId:makoId,initialSchoolId:schoolId,onSave:()=>{save();hud(true);},onBack:()=>togglePause(false),onAdvanced:hero=>openAdvancedSkillGrid(null,null,hero),onVendor:shop=>preparation.visitVendor(shop)}));}
