 for(const [parent,id]of [[$('.title-actions'),'title-dev-portal'],[$('#pause-body .menu-grid'),'pause-dev-portal']]){const a=document.createElement('a');a.id=id;a.textContent='Developer portal';a.href=target.href;a.target='_blank';a.rel='noopener';if(DEV_MODE)a.onclick=e=>{e.preventDefault();devPortal?.open();};parent?.append(a);}
