function launchSceneArtPractice(){
 if(!DEV_MODE)return;
 const params=new URL(location.href).searchParams,id=Number(params.get('reviewScene')),identity=world.scenes.get(id);
 if(!identity)return devPortal.open();
 const origin=identity.originId?originById(identity.originId):null,lead=origin?.hero??0;
 playtest?.start({chapter:identity.chapter||1,stage:'arrival',lead,party:[lead],branch:0,focus:'scene-art'});playtestTools?.started();enterJourneyView();
 world.newGame(origin?{originId:origin.id,quiet:true}:{quiet:true});
 world.state.scene=id;world.state.chapter=identity.chapter||1;world.state.party=[lead];world.state.mode='field';
 if(origin&&world.state.chronicle)world.state.chronicle.step=identity.originPart===1?2:0;
 const scene=world.scene,candidates=[scene.authoredOpening?.arrival,scene.arrive?.map(v=>v+.5)].filter(Boolean);
 if(scene.frontierAuthoring541?.version)world.state.frontierLayoutVersion=scene.frontierAuthoring541.version;
 let arrival=candidates.find(p=>world.walkable(...p));
 if(!arrival)for(let z=0;z<scene.height&&!arrival;z++)for(let x=0;x<scene.width;x++)if(world.walkable(x+.5,z+.5)){arrival=[x+.5,z+.5];break;}
 if(arrival)[world.state.x,world.state.y]=arrival;
 if(scene.biome&&id>=2000&&id<2060&&params.has('reviewJob')){
  const job=SIDE_CAMPAIGNS.find(c=>c.regionIndex===Math.floor((id-2000)/5)&&c.area===(id-2000)%5);
  if(job){const f=frontierState(world);f.active=job.id;f.stages[job.id]=Math.max(0,Math.min(3,Number(params.get('reviewJob'))||0));}
 }
 document.querySelector('#dev-portal')?.close();
 const badge=$('#dev-session-badge');if(badge){badge.hidden=false;badge.querySelector('span').textContent='DEV PLAYTEST · '+(scene.title||scene.key)+' · temporary journey';}
 finishJourneyEntry();
}
