// Optional films never advance a quest or write a save. The game stays paused.
const filmRoom=$('#film-room'),filmVideo=$('#film-video');let filmInvoker=null;
const films=await fetch('./cinema/manifest.json').then(r=>{if(!r.ok)throw Error('Film list unavailable');return r.json();}).catch(()=>({clips:[]}));
function selectFilm(clip){filmVideo.pause();filmVideo.poster=clip.poster||'';for(const b of $('#film-choices').children)b.setAttribute('aria-pressed',String(b.dataset.film===clip.src));filmVideo.src=clip.src;filmVideo.load();$('#film-title').textContent=clip.title;$('#film-note').textContent=clip.note;}
for(const clip of films.clips){const b=document.createElement('button');b.textContent=clip.title;b.dataset.film=clip.src;b.onclick=()=>selectFilm(clip);$('#film-choices').append(b);}
function openFilms(e){filmInvoker=e.currentTarget;if(started)togglePause(true);voices.stop();if(films.clips.length)selectFilm(films.clips[0]);filmRoom.showModal();syncSoundscape();queueMicrotask(()=>$('#film-close').focus());}
$('#title-films').onclick=openFilms;$('#pause-films').onclick=openFilms;
$('#film-close').onclick=()=>filmRoom.close();$('#film-replay').onclick=()=>{filmVideo.currentTime=0;filmVideo.play().catch(()=>{});};
filmRoom.addEventListener('close',()=>{filmVideo.pause();filmVideo.removeAttribute('src');filmVideo.load();filmInvoker?.focus();syncSoundscape();});
window.addEventListener('keydown',e=>{if(!filmRoom.open)return;e.stopImmediatePropagation();if(e.code==='Escape'){e.preventDefault();filmRoom.close();}},true);
window.addEventListener('keyup',e=>{if(filmRoom.open)e.stopImmediatePropagation();},true);

async function journeyAlbum(){togglePause(true);await journey.ready;$('#pause-title').textContent='Journey album';$('#pause-body').hidden=true;const panel=$('#party-panel');panel.replaceChildren();panel.hidden=false;const unlocked=journeyMemories(cinema.entries,journey.shots,world.state);const intro=document.createElement('p');intro.className='hint';intro.textContent='Your places, companions, encounters and techniques. Replays keep your progress exactly as it is.';panel.append(intro);const search=document.createElement('input');search.type='search';search.placeholder='Find a memory…';search.setAttribute('aria-label','Search earned journey memories');panel.append(search);const list=document.createElement('div');list.className='journey-memory-grid';panel.append(list);let visibleMemories=60;const render=()=>{list.replaceChildren();const q=search.value.trim().toLowerCase(),matches=unlocked.filter(e=>(e.title+' '+memoryKind(e)+' '+(e.subtitle||'')).toLowerCase().includes(q));if(!matches.length){const p=document.createElement('p');p.textContent=q?'No remembered scene matches that search.':'Places and encounters will leave memories here as you travel.';list.append(p);}for(const shot of matches.slice(0,visibleMemories)){const b=document.createElement('button'),kind=document.createElement('small'),title=document.createElement('strong');kind.textContent=memoryKind(shot)+(shot.chapter?' · Chapter '+shot.chapter:'');title.textContent=shot.title;const art=shot.shots?.[0]?.art||shot.art;if(art){const poster=document.createElement('img');poster.src='./cinema/expanded/art/'+art;poster.alt='';poster.loading='lazy';b.append(poster);}b.append(kind,title);b.onclick=()=>{if(shot.replayKind==='film')journey.play(shot,world.state,{replay:true});else cinema.present({...shot,duration:Math.max(3.5,shot.duration)},world,{force:true});};list.append(b);}if(matches.length>visibleMemories){const more=document.createElement('button');more.className='memory-more';more.textContent='Show more memories · '+(matches.length-visibleMemories)+' remaining';more.onclick=()=>{visibleMemories+=60;render();};list.append(more);}};search.oninput=()=>{visibleMemories=60;render();};render();const back=document.createElement('button');back.textContent='Back to pause';back.onclick=()=>togglePause(true);panel.append(back);back.focus();}

$('#journey-album').onclick=journeyAlbum;
window.addEventListener('keydown',e=>{if(!journey.active)return;e.stopImmediatePropagation();if(e.code==='Escape'){e.preventDefault();journey.close(true);}},true);
window.addEventListener('keyup',e=>{if(journey.active)e.stopImmediatePropagation();},true);

const loreButton=document.createElement('button');loreButton.id='world-lore-button';loreButton.textContent='World lore';loreButton.onclick=()=>{togglePause(true);$('#pause-title').textContent='World lore';$('#pause-body').hidden=true;$('#party-panel').hidden=false;lore.open(world,$('#party-panel'),()=>togglePause(true));};$('#story-button').after(loreButton);

const keyButton=document.createElement('button');keyButton.id='key-items-button';keyButton.textContent='Key items';keyButton.onclick=()=>{togglePause(true);$('#pause-title').textContent='Key items';$('#pause-body').hidden=true;$('#party-panel').hidden=false;$('#party-panel').replaceChildren(physicalSatchel(world,()=>save(),()=>togglePause(true)));};$('#bag-button').after(keyButton);

const relicButton=document.createElement('button');relicButton.id='battle-relics-button';relicButton.textContent='Battle relics & reactions';relicButton.onclick=()=>{togglePause(true);$('#pause-title').textContent='Battle relics';$('#pause-body').hidden=true;$('#party-panel').hidden=false;$('#party-panel').replaceChildren(battleRelicMenu(world,()=>save(),()=>togglePause(true)));};$('#bag-button').after(relicButton);

const guardianGearButton=document.createElement('button');guardianGearButton.id='guardian-gear-button';guardianGearButton.textContent='Guardian inheritance';guardianGearButton.onclick=()=>{togglePause(true);$('#pause-title').textContent='Guardian inheritance';$('#pause-body').hidden=true;$('#party-panel').hidden=false;$('#party-panel').replaceChildren(bossGearMenu(world,()=>save(),()=>togglePause(true)));};$('#bag-button').after(guardianGearButton);

const approachButton=document.createElement('button');approachButton.textContent='Battle approaches · your crew';$('#pause-body .menu-grid').append(approachButton);approachButton.onclick=()=>{if(battle)return notice('Choose an approach between encounters.');clearDialog();togglePause(false);approachMenu(world);};

function openEconomy(merchant=null){if(!world||battle||dialog||cinema?.busy)return;togglePause(true);$('#pause-title').textContent='The common exchange';$('#pause-body').hidden=true;$('#mako-panel').hidden=true;const panel=$('#party-panel');panel.hidden=false;panel.replaceChildren(economyPanel({world,merchant,onSave:()=>{save();hud(true);},onBack:()=>togglePause(false)}));}
const tradeButton=document.createElement('button');tradeButton.textContent='Trade satchel · community economy';$('#pause-body .menu-grid').append(tradeButton);tradeButton.onclick=()=>openEconomy();

const comfortBox=document.createElement('details');comfortBox.className='player-comfort';const comfortTitle=document.createElement('summary');comfortTitle.textContent='Display & motion';comfortBox.append(comfortTitle);function updateComfort(){const next=comfortSettings(comfort);Object.assign(comfort,next);applyDisplayFilter();if(renderer)renderer.comfort=comfort;localStorage.setItem('ash-player-comfort',JSON.stringify(comfort));}for(const [key,text] of [['screenShake','Camera shake'],['steadyLighting','Steady lighting']]){const label=document.createElement('label');label.className='setting';label.textContent=text;const input=document.createElement('input');input.type='checkbox';input.checked=comfort[key];input.onchange=()=>{comfort[key]=input.checked;updateComfort();};label.append(input);comfortBox.append(label);}const brightLabel=document.createElement('label');brightLabel.className='setting';brightLabel.textContent='Scene brightness';const brightness=document.createElement('input');brightness.type='range';brightness.min='.8';brightness.max='1.3';brightness.step='.05';brightness.value=comfort.brightness;brightness.oninput=()=>{comfort.brightness=Number(brightness.value);updateComfort();};brightLabel.append(brightness);comfortBox.append(brightLabel);cameraZoomControls=mountCameraZoomControls(comfortBox,{getManual:()=>manualZoom,getCurrent:()=>renderer?.camera.zoom||1,onChange:zoom=>setWorldZoom(zoom),onAutomatic:()=>setWorldZoom(null)});$('#pause-body').append(comfortBox);

const creaturesButton=document.createElement('button');creaturesButton.textContent='Creature field guide';$('#pause-body .menu-grid').append(creaturesButton);creaturesButton.onclick=()=>{togglePause(true);$('#pause-title').textContent='Creature field guide';$('#pause-body').hidden=true;const panel=$('#party-panel');panel.hidden=false;panel.replaceChildren(monsterFieldGuide(world,renderer,()=>togglePause(true)));};

const encounterStatus=document.createElement('span');encounterStatus.className='encounter-status';encounterStatus.hidden=true;$('#area-name').after(encounterStatus);

const graphicsSetting=document.createElement('label');graphicsSetting.className='setting';graphicsSetting.textContent='Graphics mode';const graphicsSelect=document.createElement('select');graphicsSelect.id='graphics-mode';graphicsSelect.setAttribute('aria-label','Graphics mode');for(const [value,text]of [['standard','Standard'],['compatible','Compatibility · fewer effects']])graphicsSelect.add(new Option(text,value));graphicsSelect.value=graphicsMode;graphicsSelect.onchange=()=>applyGraphicsMode(graphicsSelect.value);graphicsSetting.append(graphicsSelect);$('#pause-body').append(graphicsSetting);
const graphicsInfo=document.createElement('p');graphicsInfo.id='graphics-status';graphicsInfo.className='hint';graphicsInfo.setAttribute('role','status');$('#pause-body').append(graphicsInfo);const rebuildGraphics=document.createElement('button');rebuildGraphics.id='rebuild-graphics';rebuildGraphics.textContent='Rebuild graphics';rebuildGraphics.onclick=()=>applyGraphicsMode(graphicsMode);graphicsSetting.append(rebuildGraphics);
const titleGraphics=document.createElement('button');titleGraphics.id='graphics-help';titleGraphics.textContent='Missing characters? Try compatibility graphics';titleGraphics.onclick=()=>applyGraphicsMode(graphicsMode==='compatible'?'standard':'compatible');$('#play').parentElement.append(titleGraphics);refreshGraphicsControls();
